mapper.update:
UPDATE email_verification
SET is_verified = TRUE,
    verified_at = CURRENT_TIMESTAMP
WHERE member_id = #{memberId}
  AND email = #{email}
  AND code = #{code}
  AND is_verified = FALSE
  AND expired_at > CURRENT_TIMESTAMP
ORDER BY verification_id DESC
LIMIT 1

